430	    /** The statement summary of each person on the sheet who has had a statement taken. */
431	    @Transactional(readOnly = true)
432	    public List<Summary> list(String sheetId) {
433	        Map<Long, List<Statement>> by = new LinkedHashMap<>();
434	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
435	            by.computeIfAbsent(s.getPersonId(), (id) -> new ArrayList<>()).add(s);
436	        }
437	        return by.entrySet().stream().map((e) -> summarise(e.getKey(), e.getValue())).toList();
438	    }
439	
440	    /** A person's summary from their statements in the order they were taken; none when they have none. */
441	    private static Summary summarise(long personId, List<Statement> all) {
442	        Statement last = null;
443	        for (Statement s : all) last = last == null ? s : later(last, s);
444	        return last == null ? null : new Summary(personId, all.size(), last, List.copyOf(all));
445	    }
446	
447	    /** Of a person's last statement so far and one taken after it, which is now their last: their own
448	     *  rather than one carried to them from another. */
449	    private static Statement later(Statement last, Statement next) {
450	        return next.isCarried() && !last.isCarried() ? last : next;
451	    }
452	
453	    /** Take the person's statement: record their due-total now, bind each of their counting claims to
454	     *  the figure it shows now, and leave every other claim of theirs unbound. Taken as of a date (asOf),
455	     *  it does so with their claims as they stood at the end of that date: every change made while the
456	     *  sheet's today was on or before it counts, every later one does not, and the date stands in for the
457	     *  sheet's today in every figure. Refused for a date after the sheet's today, and one before the
458	     *  person was added. */
459	    @Transactional
460	    public Taken take(String sheetId, String user, long personId, LocalDate asOf) {
461	        Person person = people.findForUpdate(personId, sheetId)
462	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
463	        LocalDate today = sheets.today(sheetId);
464	        if (asOf != null && asOf.isAfter(today)) {
465	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
466	                    "A statement cannot be taken as of a date after the sheet's today.");
467	        }
468	        if (asOf != null && person.getAddedOn() != null && asOf.isBefore(person.getAddedOn())) {
469	            throw new ResponseStatusException(HttpStatus.CONFLICT,
470	                    person.getName() + " was not yet on the sheet on " + asOf + ".");
471	        }
472	        LocalDate on = asOf != null ? asOf : today;
473	        DatedSettings dated = asOf != null ? settings.datedAsOf(sheetId, asOf) : settings.dated(sheetId);
474	        Rollup.Snapshot before = rollup.snapshot(sheetId);
475	        List<Claim> theirs = claims.findForStatement(sheetId, personId);
476	        BigDecimal total = BigDecimal.ZERO.setScale(2);
477	        boolean keptFigure = false;
478	        int counting = 0;
479	        for (Claim claim : theirs) {
480	            Stood stood = asOf != null ? stoodAsOf(sheetId, person, claim, asOf, dated) : stoodNow(sheetId, person, claim, today);
481	            if (stood == null) {
482	                claim.unbind(today);
483	                continue;
484	            }
485	            counting++;
486	            if (stood.due() != null) total = total.add(stood.due());
487	            if (stood.keptFigure()) keptFigure = true;
488	            claim.bind(stood.figure(), today);
489	        }
490	        // As the screen shows it: n/a when no rate of the grade in force on the statement's date is in force
491	        // then and no claim keeps a figure; held to the sheet's cap.
492	        Grade grade = person.gradeOn(on, asOf);
493	        boolean noRate = (asOf != null ? rates.inForceAsOf(sheetId, grade, on, asOf) : rates.inForce(sheetId, grade, on)) == null;
494	        BigDecimal dueTotal = SettingService.capped(noRate && !keptFigure ? null : total, dated.capOn(on));
495	        claims.saveAllAndFlush(theirs);
496	        statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, counting, today, on, user));
497	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
498	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counting
499	                + (asOf == null ? "" : " asof=" + asOf));
500	        rollup.recordChanges(user, before);
501	        return new Taken(summarise(personId, statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId)),
502	                theirs);
503	    }
504	
505	    /** How a counting claim stood for a statement: the figure it binds (before late charge and floor; null:
506	     *  n/a), its due, and whether it keeps a figure should the grade's rate be n/a. */
507	    private record Stood(BigDecimal figure, BigDecimal due, boolean keptFigure) {
508	    }
509	
510	    /** How the claim stands now; null when it does not count. */
511	    private Stood stoodNow(String sheetId, Person person, Claim claim, LocalDate today) {
512	        if (!counts(person, claim, today)) return null;
513	        // The statement binds the rate figure, before late charge and floor; the due-total it records is the due.
514	        BigDecimal figure = claimService.figure(sheetId, person, claim);
515	        BigDecimal due = claimService.due(sheetId, person, claim);
516	        boolean kept = claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
517	                // A live figure at a grade other than today's is not undone by today's grade having no rate.
518	                || (figure != null && person.gradeOn(claim.getDate()) != person.gradeOn(today))
519	                // Nor is a live figure on a claim dated by today undone by its rate having ended since.
520	                || (figure != null && !claim.getDate().isAfter(today));
521	        return new Stood(figure, due, kept);
522	    }
523	
524	    /** How the claim stood at the end of the date (asOf), which stands in for the sheet's today: its status,
525	     *  settled due and binding then, the grade, rate, floor, late percent and holds and retirement in force
526	     *  as they stood then; null when it did not count then (or was not yet added). */
527	    private Stood stoodAsOf(String sheetId, Person person, Claim claim, LocalDate asOf, DatedSettings dated) {
528	        ClaimStatus status = claim.statusAsOf(asOf);
529	        if (status == null) return null;
530	        BigDecimal settled = status == ClaimStatus.SETTLED ? claim.settledDueAsOf(asOf) : null;
531	        ClaimBinding binding = claim.bindingAsOf(asOf);
532	        boolean deferred = status == ClaimStatus.OPEN && claim.getDeferredUntil() != null
533	                && asOf.isBefore(claim.getDeferredUntil());
534	        boolean counts = status == ClaimStatus.SETTLED || (status.isOpen() && !deferred
535	                && (binding != null || !person.isLeftOutAsOf(claim.getDate(), asOf)));
536	        if (!counts) return null;
537	        RoundingMode rounding = claimService.rounding(sheetId, claim, asOf, dated);
538	        Grade grade = person.gradeOn(claim.getDate(), asOf);
539	        BigDecimal figure;
540	        if (settled != null) {
541	            figure = settled;
542	        } else if (binding != null) {
543	            figure = binding.getStatedDue();
544	        } else {
545	            Rate rate = rates.inForceAsOf(sheetId, grade, claim.getDate(), asOf, claim.getId());
546	            figure = rate == null ? null
547	                    : claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2, rounding);
548	        }
549	        BigDecimal floor = dated.floorOn(claim.getDate());
550	        BigDecimal due;
551	        if (figure == null || settled != null) {
552	            due = figure;
553	        } else if (status.isOpen() && !deferred) {
554	            due = LateCharge.dueAsOpen(claim, figure, floor, asOf, dated.graceOn(grade, claim.getDate()),
555	                    dated::latePctOn, rounding);
556	        } else {
557	            due = LateCharge.floored(claim, figure, floor);
558	        }
559	        boolean kept = settled != null || (binding != null && binding.getStatedDue() != null)
560	                || (figure != null && grade != person.gradeOn(asOf, asOf))
561	                || (figure != null && !claim.getDate().isAfter(asOf));
562	        return new Stood(figure, due, kept);
563	    }
