565	    /** A statement just cancelled: the person's summary after it (none when no statement is left), and
566	     *  their claims, live again, newest first. */
567	    public record Cancelled(Summary summary, List<Claim> claims) {
568	    }
569	
570	    /** Cancel the person's last statement: the claims it bound are live again (a figure an earlier
571	     *  statement bound is not restored) and the statement before it is their last (one carried to them
572	     *  only when none of their own is left). Refused unless the
573	     *  user is a steward of the sheet, or when the person has no statement. */
574	    @Transactional
575	    public Cancelled cancel(String sheetId, String user, long personId) {
576	        Person person = people.findForUpdate(personId, sheetId)
577	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
578	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
579	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward cancels a statement.");
580	        }
581	        List<Statement> all = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
582	        if (all.isEmpty()) {
583	            throw new ResponseStatusException(HttpStatus.CONFLICT, person.getName() + " has no statement to cancel.");
584	        }
585	        Statement last = summarise(personId, all).last();
586	        Rollup.Snapshot before = rollup.snapshot(sheetId);
587	        List<Claim> theirs = claims.findForStatement(sheetId, personId);
588	        // Only the last statement binds claims, so every claim it bound is unbound.
589	        LocalDate today = sheets.today(sheetId);
590	        theirs.forEach((claim) -> claim.unbind(today));
591	        claims.saveAllAndFlush(theirs);
592	        statements.delete(last);
593	        statements.flush();
594	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
595	                + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString()));
596	        rollup.recordChanges(user, before);
597	        List<Statement> left = all.stream().filter((s) -> s != last).toList();
598	        return new Cancelled(summarise(personId, left), theirs);
599	    }
600	
601	    /** Only open and settled claims count toward what is claimed and due; a person's open claims dated
602	     *  within one of their holds, or all of them once their retirement date is reached, do not, unless a
603	     *  statement binds them, nor does a claim deferred on the
604	     *  sheet's today, as on the screen. */
605	    private static boolean counts(Person person, Claim claim, LocalDate today) {
606	        return claim.getStatus() == ClaimStatus.SETTLED
607	                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
608	                        && (claim.isBound() || !person.isLeftOut(claim.getDate(), today)));
609	    }
610	}
611	package net.officefloor.hq.app.claim;
612	
613	import java.math.BigDecimal;
614	import java.math.RoundingMode;
615	import java.time.LocalDate;
616	import java.time.temporal.ChronoUnit;
617	import java.util.function.Function;
618	
619	/**
620	 * The late charge on a claim: an open claim past its due-by (fixed when it was added) gains, for every
621	 * full 30 days it is overdue, the sheet's late percent in force on that boundary (the due-by plus 30, 60,
622	 * 90 ... days, counted from the due-by plus the grace days of its person's grade, if any) of its figure plus the
623	 * charges of the boundaries before it (compounding), each rounded as the claim's {@link Rounding} decides, like due, and added up;
624	 * a boundary whose percent is 0.00 adds nothing, and a correction or a waived claim gains none. The charge is worked out on the rate figure alone (or the
625	 * figure a statement bound), before the floor, which is applied last. A statement never binds the charge; it follows the sheet's today until the claim is settled.
626	 */
627	public final class LateCharge {
628	
629	    /** The days a claim must be overdue for each step of the late charge. */
630	    public static final int DAYS_PER_CHARGE = 30;
631	
632	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
633	
634	    private LateCharge() {
635	    }
636	
637	    /** The late charge on the claim of the figure (null: n/a, and no charge) on the sheet's today; none
638	     *  while the claim is deferred, as it is not overdue then. */
639	    public static BigDecimal of(Claim claim, BigDecimal figure, LocalDate today,
640	            int grace, Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
641	        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) ? asOpen(claim, figure, today, grace, latePctOn, rounding) : ZERO;
642	    }
643	
644	    /** The late charge the claim of the figure would have on the sheet's today were it open. */
645	    private static BigDecimal asOpen(Claim claim, BigDecimal figure, LocalDate today,
646	            int grace, Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
647	        if (figure == null || today == null || claim.isCorrection() || claim.isWaived()) return ZERO;
648	        LocalDate lateFrom = lateFrom(claim, grace);
649	        long overdueDays = ChronoUnit.DAYS.between(lateFrom, today);
650	        long steps = overdueDays <= 0 ? 0 : overdueDays / DAYS_PER_CHARGE;
651	        BigDecimal charge = ZERO;
652	        for (long step = 1; step <= steps; step++) {
653	            BigDecimal pct = latePctOn.apply(lateFrom.plusDays(step * DAYS_PER_CHARGE));
654	            charge = charge.add(figure.add(charge).multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding));
655	        }
656	        return charge;
657	    }
658	
659	    /** The claim's due of the figure (null: n/a): a due fixed when it was settled stays as it is; else the
660	     *  figure with its late charge on top, and at least the floor, the floor applied last (a correction has
661	     *  no floor and no charge); null when the figure is n/a. */
662	    public static BigDecimal dueOf(Claim claim, BigDecimal figure, BigDecimal floor, LocalDate today,
663	            int grace, Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
664	        if (figure == null || claim.getSettledDue() != null) return figure;
665	        return floored(claim, figure.add(of(claim, figure, today, grace, latePctOn, rounding)), floor);
666	    }
667	
668	    /** The claim's due of the figure as it would be were the claim open: the figure with the late charge it
669	     *  would have on top, and at least the floor, applied last; null when the figure is n/a. */
670	    public static BigDecimal dueAsOpen(Claim claim, BigDecimal figure, BigDecimal floor, LocalDate today,
671	            int grace, Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
672	        return figure == null ? null : floored(claim, figure.add(asOpen(claim, figure, today, grace, latePctOn, rounding)), floor);
673	    }
674	
675	    /** The date the claim's lateness counts from: its due-by plus the grace days of its person's grade in
676	     *  force on its date; the due-by shown is unchanged. */
677	    public static LocalDate lateFrom(Claim claim, int grace) {
678	        return claim.getDueBy().plusDays(grace);
679	    }
680	
681	    /** The due held to at least the floor, unless the claim is a correction, which has no floor. */
682	    public static BigDecimal floored(Claim claim, BigDecimal due, BigDecimal floor) {
683	        return claim.isCorrection() ? due : due.max(floor);
684	    }
685	}
