  const steps = Math.floor((epochDay(late.today) - dueBy) / DAYS_PER_CHARGE);
  let charge = 0;
  for (let step = 1; step <= steps; step++) {
    charge += dueCents(figureCents + charge, late.latePct(dateOfEpochDay(dueBy + step * DAYS_PER_CHARGE)), halfUp);
